cypress_script:
describe('Numeric Input Field Validation', () => {
  it('should accept a valid numeric input', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').type('123').should('have.value', '123');
  });

  it('should not change URL on invalid input', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').clear().type('abc');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/inputs');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Numeric Input Field Validation', () => {
  test('should accept a valid numeric input', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/inputs');
    await page.fill('input[type="number"]', '123');
    const value = await page.inputValue('input[type="number"]');
    expect(value).toBe('123');
  });

  test('should not change URL on invalid input', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/inputs');
    const initialUrl = page.url();
    await page.fill('input[type="number"]', 'abc');
    expect(page.url()).toBe(initialUrl);
  });
});
